function formatIcsEvent(name, timeIn, timeOut, location, UID) {
    // Generate UID from timeIn and timeOut
    const uid = `${UID}@craftedgoods.ca`;
    const now = new Date().toISOString().replace(/[-:]/g, '').replace('.000', '');

    return `BEGIN:VEVENT\r\n` +
           `UID:${uid}\r\n` +
           `DTSTAMP:${now}\r\n` +
           `DTSTART:${timeIn}\r\n` +
           `DTEND:${timeOut}\r\n` +
           `LOCATION:${location}\r\n` +
           `SUMMARY:${name}\r\n` +
           `END:VEVENT\r\n`;
}

function generateUID() {
    return Math.random().toString(36).substr(2, 9) + '@craftedgoods.ca';
}

function exportToCalendar() {
    // Get all elements with the class "employee-entry"
    const dayElements = document.querySelectorAll('.employee-entry');

    // Start of the ICS content
    let content = `BEGIN:VCALENDAR\r\n` +
                  `VERSION:2.0\r\n` +
                  `PRODID:-//CRAFTED//My Shifts//EN\r\n`;

    // For each day item, format it as an ICS event
    dayElements.forEach(el => {
        const name = el.getAttribute('data-name');
        const timeIn = el.getAttribute('data-time-in');
        const timeOut = el.getAttribute('data-time-out');
        const location = el.getAttribute('data-location');
        const UID = el.getAttribute('data-UID');
        content += formatIcsEvent(name, timeIn, timeOut, location, UID);
    });

    // End of the ICS content
    content += `END:VCALENDAR\r\n`;

    // Create a blob object representing the content
    const blob = new Blob([content], { type: 'text/calendar' });

    // Create a link element
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'events.ics'; // set the file name

    // Append the link to the document
    document.body.appendChild(a);

    // Trigger a click event on the link
    a.click();

    // Remove the link from the document
    document.body.removeChild(a);
}
document.addEventListener('DOMContentLoaded', function() {
    const employeeCheckboxes = document.querySelectorAll('.filterEmployee');
    const outletCheckboxes = document.querySelectorAll('.filterOutlet');
    employeeCheckboxes.forEach(cb => cb.addEventListener('change', applyFilter));
    outletCheckboxes.forEach(cb => cb.addEventListener('change', applyFilter));
    const masterOutletCheckbox = document.getElementById('masterOutletCheckbox');
    masterOutletCheckbox.addEventListener('change', function() {
        if (masterOutletCheckbox.checked) {
            checkAllOutletCheckboxes();
        } else {
            uncheckAllOutletCheckboxes();
        }
    });
    const masterEmployeeCheckbox = document.getElementById('masterEmployeeCheckbox');
    masterEmployeeCheckbox.addEventListener('change', function() {
        if (masterEmployeeCheckbox.checked) {
            checkAllEmployeeCheckboxes();
        } else {
            uncheckAllEmployeeCheckboxes();
        }
    });
});

function applyFilter() {
    const selectedEmployees = Array.from(document.querySelectorAll('.filterEmployee:checked')).map(cb => cb.value);
    const selectedOutlets = Array.from(document.querySelectorAll('.filterOutlet:checked')).map(cb => cb.value);
    const entries = document.querySelectorAll('.employee-entry, .employee-other');
    entries.forEach(entry => {
        const entryEmployee = entry.getAttribute('data-preferred-name');
        const entryOutlet = entry.getAttribute('data-location');
        
        const isEmployeeSelected = selectedEmployees.includes(entryEmployee);
        const isOutletSelected = selectedOutlets.includes(entryOutlet);

        // Only show the entry if it matches the filters
        entry.style.display = (isEmployeeSelected && isOutletSelected) ? 'block' : 'none';
    });
}


function checkAllOutletCheckboxes() {
    const outletCheckboxes = document.querySelectorAll('.filterOutlet');
    outletCheckboxes.forEach(cb => cb.checked = true);
    applyFilter();
}

function uncheckAllOutletCheckboxes() {
    const outletCheckboxes = document.querySelectorAll('.filterOutlet');
    outletCheckboxes.forEach(cb => cb.checked = false);
    applyFilter();
}



function checkAllEmployeeCheckboxes() {
    const employeeCheckboxes = document.querySelectorAll('.filterEmployee');
    employeeCheckboxes.forEach(cb => cb.checked = true);
    applyFilter();
}
function uncheckAllEmployeeCheckboxes() {
    const employeeCheckboxes = document.querySelectorAll('.filterEmployee');
    employeeCheckboxes.forEach(cb => cb.checked = false);
    applyFilter();
}


applyFilter();

css:
/* Desk-like My Shifts — aligned with Manage Shifts */
.page-content-wrapper .main-column,
.web-page-content {
  max-width: 1200px !important;
}

.mgr-page {
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 13px;
  color: #36414c;
  line-height: 1.45;
  padding: 8px 4px 32px;
}

.mgr-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin: 0 0 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid #d1d8dd;
}
.mgr-toolbar h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: #2c3338;
}
.mgr-toolbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.mgr-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #fff;
  color: #2490ef;
  border: 1px solid #2490ef;
  border-radius: 6px;
  padding: 6px 12px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
}
.mgr-btn:hover { background: #f0f8ff; color: #1a7fd1; text-decoration: none; }
.mgr-btn.primary { background: #2490ef; color: #fff; border-color: #2490ef; }
.mgr-btn.primary:hover { background: #1a7fd1; color: #fff; }
.mgr-btn.secondary { color: #36414c; border-color: #d1d8dd; }
.mgr-btn.secondary:hover { background: #f5f7fa; color: #36414c; }

.mgr-hint { color: #6c7680; font-size: 12px; margin: 0 0 14px; }

.mgr-layout {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 16px;
  align-items: start;
}
@media (max-width: 900px) {
  .mgr-layout { grid-template-columns: 1fr; }
}

.mgr-filters {
  background: #fff;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  padding: 12px;
  position: sticky;
  top: 12px;
  max-height: calc(100vh - 40px);
  overflow: auto;
}
.mgr-filter-block { margin-bottom: 14px; }
.mgr-filter-block:last-child { margin-bottom: 0; }
.mgr-filter-title {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6c7680;
  margin: 0 0 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid #eef0f2;
}
.mgr-filter-list label {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 0 0 6px;
  font-size: 13px;
  color: #36414c;
  cursor: pointer;
  font-weight: 400;
}
.mgr-filter-list input[type="checkbox"] {
  margin-top: 2px;
  accent-color: #2490ef;
}
.All-label { font-weight: 600 !important; color: #2c3338 !important; }

.mgr-calendar-wrap {
  background: #fff;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  overflow: hidden;
}

.calendar-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0;
  margin: 0;
}
.calendar-days > .title {
  padding: 8px 6px;
  text-align: center;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: #6c7680;
  background: #f5f7fa;
  border-bottom: 1px solid #d1d8dd;
  border-right: 1px solid #eef0f2;
}
.day, .past-day, .today {
  min-height: 110px;
  padding: 6px;
  text-align: left;
  border-right: 1px solid #eef0f2;
  border-bottom: 1px solid #eef0f2;
  background: #fff;
  font-size: 12px;
  font-weight: 600;
  color: #2c3338;
}
.past-day { background: #fafbfc; color: #98a1a9; }
.today {
  background: #f0f8ff;
  box-shadow: inset 0 0 0 2px #2490ef;
}

.employee-entry,
.employee-other {
  display: block;
  margin: 4px 0 0;
  padding: 4px 6px;
  border: none;
  border-left: 3px solid rgba(0,0,0,0.25);
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
  color: #1f272e;
  box-shadow: 0 0 0 1px rgba(0,0,0,0.06);
}
.employee-entry {
  border-left-width: 4px;
  font-weight: 600;
}

.Requested-time-off,
.Approved-time-off {
  margin: 4px 0 0;
  padding: 4px 6px;
  border: none;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
}
.Requested-time-off {
  background: #fff4e5;
  color: #c05600;
  box-shadow: 0 0 0 1px #f6ad55;
}
.Approved-time-off {
  background: #fff0f0;
  color: #a33;
  box-shadow: 0 0 0 1px #f5c6c6;
}

.mgr-coming {
  margin-top: 16px;
  background: #fff;
  border: 1px solid #d1d8dd;
  border-radius: 8px;
  padding: 12px 14px;
}
.mgr-coming h3 {
  margin: 0 0 10px;
  font-size: 14px;
  font-weight: 600;
}
.Leaves {
  width: 100%;
  border-collapse: collapse;
  table-layout: auto;
}
.Leaves td {
  padding: 6px 8px;
  border-bottom: 1px solid #eef0f2;
  font-size: 13px;
  font-weight: 400;
}

.PayDay {
  border-radius: 4px;
  margin-top: 5px;
  font-size: 11px;
  background: #fff0f0;
  color: #a33;
  padding: 4px 6px;
}
.outlet-entry { font-size: 13px; }
